  @override void dispose(){timer?.cancel();unregisterFileDrop(drop);for(final x in c.values)x.dispose();super.dispose();}
  double d(String k)=>double.parse(c[k]!.text.replaceAll(',','.')); int i(String k)=>int.parse(c[k]!.text);
  Future<void> _pick()async{final f=await pickFiles(extensions:const['dxf']);if(f.isNotEmpty)_load(f.first);}
  void _load(PickedFile f){try{final doc=DxfParser.parseBytes(f.bytes);setState((){document=doc;fileName=f.fileName;error=null;program=null;motion=0;});_generate();}catch(e){setState(()=>error=e.toString().replaceFirst('FormatException: ',''));}}
  void _generate(){if(document==null)return;try{final p=NcParameters(drawingName:fileName!,programNumber:c['program']!.text.toUpperCase(),thickness:d('thickness'),toolNumber:i('tool'),toolName:c['toolName']!.text,toolDiameter:d('diameter'),spindleSpeed:i('spindle'),cuttingFeed:i('feed'),plungeFeed:i('plunge'),safeZ:d('safe'),startZ:d('start'),finalDepth:d('final'),depthPerPass:d('pass'),direction:direction,internalOffset:d('internal'),externalOffset:d('external'),coordinateScale:d('scale'),xOrigin:d('x'),yOrigin:d('y'),controllerCompensation:controllerComp);setState((){program=NcGenerator.generateProgram(document!,p);error=null;motion=0;});}catch(e){setState((){program=null;error=e.toString().replaceFirst('Invalid argument(s): ', '');});}}
  Future<void> _download()=>downloadBytes(bytes:Uint8List.fromList(utf8.encode(program!.text)),fileName:'${fileName!.replaceFirst(RegExp(r'\.dxf$',caseSensitive:false),'')}.nc',mimeType:'text/plain;charset=utf-8');
