  Widget _settings()=>AppCard(title:'Program & machining setup',child:Column(children:[InkWell(onTap:_pick,child:Container(width:double.infinity,padding:const EdgeInsets.all(18),decoration:BoxDecoration(border:Border.all(color:AppColors.darkBlue),borderRadius:BorderRadius.circular(10)),child:Column(children:[const Icon(Icons.file_upload_outlined,size:32),Text(fileName??'Drop or choose a DXF',style:const TextStyle(fontWeight:FontWeight.bold)),Text(document==null?'LINE · ARC · CIRCLE · POLYLINE':'${document!.entities.length} entities loaded')]))),const SizedBox(height:14),_row('program','Program','thickness','Glass thickness',s2:'mm'),_row('tool','Tool number','toolName','Tool name',numeric2:false),_row('diameter','Tool diameter','spindle','Spindle',s1:'mm',s2:'rpm'),_row('feed','XY cutting feed','plunge','Z plunge feed',s1:'mm/min',s2:'mm/min'),_row('safe','Safe Z','start','Start Z',s1:'mm',s2:'mm'),_row('final','Final depth','pass','Depth / pass',s1:'mm',s2:'mm'),_row('internal','Internal offset','external','External offset',s1:'mm',s2:'mm'),_row('scale','Coordinate scale','x','X origin'),_field('y','Y origin'),const SizedBox(height:8),Row(children:[const Text('Direction'),const Spacer(),ChoiceChip(label:const Text('CW'),selected:direction==CuttingDirection.cw,onSelected:(_)=>setState(()=>direction=CuttingDirection.cw)),const SizedBox(width:6),ChoiceChip(label:const Text('CCW'),selected:direction==CuttingDirection.ccw,onSelected:(_)=>setState(()=>direction=CuttingDirection.ccw))]),SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('Use controller G41/G42'),subtitle:const Text('Off: geometric tool-radius offset'),value:controllerComp,onChanged:(v)=>setState(()=>controllerComp=v)),FilledButton.icon(onPressed:document==null?null:_generate,icon:const Icon(Icons.precision_manufacturing),label:const Text('Generate complete NC')),if(error!=null)Padding(padding:const EdgeInsets.only(top:10),child:Text(error!,style:const TextStyle(color:AppColors.error)))]));
  Widget _row(String a,String la,String b,String lb,{String? s1,String? s2,bool numeric2=true})=>Padding(padding:const EdgeInsets.only(bottom:10),child:Row(children:[Expanded(child:_field(a,la,s:s1)),const SizedBox(width:10),Expanded(child:_field(b,lb,s:s2,numeric:numeric2))]));
  Widget _field(String k,String label,{String? s,bool numeric=true})=>TextField(controller:c[k],keyboardType:numeric?const TextInputType.numberWithOptions(decimal:true,signed:true):null,decoration:InputDecoration(labelText:label,suffixText:s));
  Widget _workspace(){final a=program?.analysis;return Column(children:[AppCard(title:'Drawing analysis & toolpaths',child:Column(children:[if(a!=null)Wrap(spacing:20,runSpacing:8,children:[_metric('Width','${a.width.toStringAsFixed(2)} mm'),_metric('Height','${a.height.toStringAsFixed(2)} mm'),_metric('Contours','${a.contours.length}'),_metric('Closed','${a.contours.where((x)=>x.closed).length}')]),if(a?.warnings.isNotEmpty??false)...a!.warnings.map((w)=>ListTile(dense:true,leading:const Icon(Icons.warning_amber,color:Colors.orange),title:Text(w))),SizedBox(height:350,width:double.infinity,child:document==null?const Center(child:Text('Upload a DXF to inspect all geometry.')):CustomPaint(painter:_ToolpathPainter(document!,a,program?.motions,motion)))])),const SizedBox(height:16),_simulation(),const SizedBox(height:16),AppCard(title:'Generated NC program',child:Container(height:370,width:double.infinity,padding:const EdgeInsets.all(14),color:const Color(0xff101827),child:SingleChildScrollView(child:SelectableText(program?.text??'Generate a program to preview NC output.',style:const TextStyle(fontFamily:'monospace',color:Color(0xffe5e7eb),height:1.4)))))]);}
  Widget _metric(String a,String b)=>Chip(label:Text('$a  $b'));
  Widget _simulation(){final m=program==null||program!.motions.isEmpty?null:program!.motions[motion.clamp(0,program!.motions.length-1)];return AppCard(title:'Machining simulation',child:Column(children:[Row(children:[IconButton(onPressed:_play,icon:const Icon(Icons.play_arrow)),IconButton(onPressed:_pause,icon:const Icon(Icons.pause)),IconButton(onPressed:_restart,icon:const Icon(Icons.replay)),const Text('Speed'),Expanded(child:Slider(value:speed,min:.25,max:4,divisions:15,label:'${speed.toStringAsFixed(2)}×',onChanged:(v)=>setState(()=>speed=v))]),if(m!=null)...[LinearProgressIndicator(value:(motion+1)/program!.motions.length),const SizedBox(height:8),Wrap(spacing:18,children:[Text('X ${m.end.x.toStringAsFixed(3)}'),Text('Y ${m.end.y.toStringAsFixed(3)}'),Text('Z ${m.end.z.toStringAsFixed(3)}'),Text('NC line ${m.line}'),Text(m.type.name.toUpperCase(),style:const TextStyle(fontWeight:FontWeight.bold))]),const SizedBox(height:8),Container(width:double.infinity,padding:const EdgeInsets.all(8),color:const Color(0xff101827),child:Text(program!.text.split('\n')[m.line-1],style:const TextStyle(color:Colors.amber,fontFamily:'monospace',fontWeight:FontWeight.bold))) ])) );}
}
class _ToolpathPainter extends CustomPainter{const _ToolpathPainter(this.doc,this.analysis,this.motions,this.active);final DxfDocument doc;final DrawingAnalysis? analysis;final List<NcMotion>? motions;final int active;@override void paint(Canvas canvas,Size size){final pts=doc.points.toList();if(pts.isEmpty)return;final minX=pts.map((p)=>p.x).reduce(math.min),maxX=pts.map((p)=>p.x).reduce(math.max),minY=pts.map((p)=>p.y).reduce(math.min),maxY=pts.map((p)=>p.y).reduce(math.max),scale=math.min((size.width-30)/math.max(1,maxX-minX),(size.height-30)/math.max(1,maxY-minY));Offset q(double x,double y)=>Offset(15+(x-minX)*scale,size.height-15-(y-minY)*scale);for(var ci=0;ci<(analysis?.contours.length??0);ci++){final paint=Paint()..style=PaintingStyle.stroke..strokeWidth=(motions!=null&&motions!.isNotEmpty&&motions![active.clamp(0,motions!.length-1)].contour==ci)?3:1.5..color=analysis!.contours[ci].kind==ContourKind.externalPerimeter?Colors.blue:Colors.teal;for(final s in analysis!.contours[ci].segments){if(s is LineSegment)canvas.drawLine(q(s.start.x,s.start.y),q(s.end.x,s.end.y),paint);if(s is ArcSegment){var a1=math.atan2(-(s.start.y-s.center.y),s.start.x-s.center.x),a2=math.atan2(-(s.end.y-s.center.y),s.end.x-s.center.x),sweep=a2-a1;if(s.fullCircle)sweep=s.clockwise?2*math.pi:-2*math.pi;else if(s.clockwise&&sweep<0)sweep+=2*math.pi;else if(!s.clockwise&&sweep>0)sweep-=2*math.pi;canvas.drawArc(Rect.fromCircle(center:q(s.center.x,s.center.y),radius:s.radius*scale),a1,sweep,false,paint);}}}if(motions!=null&&motions!.isNotEmpty){final p=motions![active.clamp(0,motions!.length-1)].end;canvas.drawCircle(q(p.x,p.y),6,Paint()..color=Colors.red);}}@override bool shouldRepaint(covariant _ToolpathPainter old)=>true;}
